function chart(rows,s){const curves=rows.filter(r=>r.curve.length>1),points=curves.flatMap(r=>r.curve.map(p=>p.T));let low=Math.floor((Math.min(...points)-2)/5)*5,high=Math.ceil((Math.max(...points)+2)/5)*5;if(high-low<10)high=low+10;const end=s.mode==='batch'?s.minutes:s.L,X=x=>65+640*x/end,Y=t=>210-(t-low)/(high-low)*175;let grid='';for(let i=0;i<=4;i++){const t=low+(high-low)*i/4,y=Y(t);grid+=`<line x1="65" y1="${y}" x2="705" y2="${y}" stroke="#e5ece9"/><text x="55" y="${y+4}" text-anchor="end" fill="#74858a" font-size="10">${f(t,0)}</text>`;}for(let i=0;i<=4;i++)grid+=`<text x="${65+640*i/4}" y="233" text-anchor="middle" fill="#74858a" font-size="10">${f(end*i/4,1)}</text>`;return `<svg viewBox="0 0 760 264" role="img" aria-label="四种方案的钢液温度变化对比"><text x="18" y="18" fill="#74858a" font-size="10">温度 / °C</text>${grid}${curves.map(r=>`<path d="${r.curve.map((p,i)=>`${i?'L':'M'}${X(p.x).toFixed(2)} ${Y(p.T).toFixed(2)}`).join(' ')}" fill="none" stroke="${colors[r.type]}" stroke-width="${r.type===s.selected?3:1.7}" ${r.type==='none'?'stroke-dasharray="5 4"':''}/>`).join('')}<text x="705" y="258" text-anchor="end" fill="#74858a" font-size="10">${s.mode==='batch'?'保温时长 / min':'沿槽长 / m（均匀分布热源近似）'}</text></svg>`;}
