 const grossKW=s.selected==='powder'?r.powder.reactionMJ/3.6*src.tonnes/src.durationH:src.main,sourceLabel=s.selected==='powder'?'已完成反应的标准热':'主机输入（不含辅机）',convLoss=grossKW-src.deposited,avgLoss=valid?x.lossKWh/src.durationH:null;
 $('#energy-flow').innerHTML=`<div class="energy-cell"><span>${sourceLabel}</span><b>${f(grossKW)} <small>kW</small></b></div><span class="energy-arrow">→</span><div class="energy-cell"><span>沉积到钢液的热功率</span><b>${f(src.deposited)} <small>kW</small></b></div><span class="energy-arrow">−</span><div class="energy-cell"><span>沿程 / 全时段平均散热</span><b>${f(avgLoss)} <small>kW</small></b></div><span class="energy-arrow">=</span><div class="energy-cell"><span>钢液显热净功率${s.startupKWh>0?'（另扣蓄热）':''}</span><b>${valid?signed(x.stored/src.durationH):'—'} <small>kW</small></b></div>`;
