function renderLengths(){const values=[2,4,6,8,10,12];if(!values.includes(s.L)&&s.L<=100)values.push(s.L);values.sort((a,b)=>a-b);$('#length-note').textContent=s.mode==='continuous'?`固定宽度、液深与 ${f(s.flow)} t/h；铺设上限保持 ${f(s.heatLength)} m，等离子总功率与粉末kg/t不变。槽长增加会增加存量、停留时间和散热。电量按各自一个停留时间核算。`:`固定宽度、液深与 ${f(s.minutes)} min保温时长；槽长增加同时增加钢液重量。电磁铺设上限保持 ${f(s.heatLength)} m，等离子总功率不变。`;
 $('#length-study').innerHTML=table(['槽长 m','钢液 t','核算 min','总损失 kW²','电输入 kW','本窗电量 kWh','电耗 kWh/t','净温变 °C','少降温 °C'],values.map(L=>{const v={...s,L},a=run(v),b=run(v,'none');if(a.errors.length)return `<tr><td>${f(L)}</td><td colspan="8">该长度下停留时间超出180 min核算范围</td></tr>`;return `<tr class="${L===s.L?'selected':''}"><td><button data-length="${L}" aria-label="设槽长为${L}米">${f(L)}</button></td><td>${f(a.g.tonnes,2)}</td><td>${f(a.src.durationH*60)}</td><td>${f(a.initial.total)}</td><td>${f(a.src.input)}</td><td>${f(a.src.electricKWh)}</td><td>${f(a.src.kWhT,2)}</td><td>${a.limited?'温区外':signed(a.delta)}</td><td>${a.limited||b.limited?'—':f(a.T-b.T)}</td></tr>`;}).join(''));}
function renderLedger(r){const x=r.selected,src=x.src,p=r.powder;const chemical=s.selected==='powder'?s.powderDose*src.tonnes*POWDERS[s.powder].heat/3.6:0;const eff=s.selected==='powder'?(chemical>0?src.deposited*src.durationH/chemical:null):src.main>0?src.deposited/src.main:null;const totalInput=src.electricKWh+chemical;const rows=[['入钢热沉积效率',eff===null?'—':f(eff*100,1)+'%',s.selected==='powder'?'粉末标准化学能→钢液净沉积；已含供氧约束与额外吸热':'主机电输入→钢液沉积；尚未扣槽体热损失'],['系统显热净利用率',x.limited||totalInput<=0?'—':f(x.stored/totalInput*100,1)+'%','钢液净显热 /（电能+供粉标准化学能）；可为负'],['核算时间',f(src.durationH*60)+' min',s.mode==='continuous'?'平均停留时间；对应一槽存量的通过量':'单批保温时长'],['处理钢液',f(src.tonnes,3)+' t',s.mode==='continuous'?`处理量 ${f(s.flow)} t/h`:'矩形槽内钢液存量'],['主机耗电',f(src.main*src.durationH,2)+' kWh',f(src.main*src.durationH/src.tonnes,2)+' kWh/t'],['辅助耗电',f(src.aux*src.durationH,2)+' kWh',f(src.aux*src.durationH/src.tonnes,2)+' kWh/t'],['总电费',f(src.electricKWh*s.price,2)+' 元',`电价 ${f(s.price,2)} 元/kWh，不含粉末、氧气与耐材成本`],['粉末',f(src.powder,2)+' kg',s.selected==='powder'?`${f(s.powderDose,2)} kg/t；${f(src.powder/(src.durationH*60),2)} kg/min，均匀加入`:'本方案不加粉'],['供入纯氧',f(src.oxygen,2)+' Nm³',s.selected==='powder'?`${f(s.oxygen,2)} Nm³/t；标准态0°C、1 atm`:'不含现场另设气体'],['反应产物',s.selected==='powder'?f(p.product*src.tonnes,2)+' kg':'0 kg',s.selected==='powder'?p.productLabel+'；不等于渣或尾气的全部组成':'—'],['槽体散失热量',x.limited?'温区外':f(x.lossKWh,2)+' kWh','² 表中总损失功率为入口温度条件；此处按变化温度积分'],['额外耐材蓄热',f(s.startupKWh,2)+' kWh','一次核算窗内给定负荷，不含完整冷衬模型'],['钢液显热净变化',x.limited?'温区外':signed(x.stored)+' kWh','负值表示钢液冷却；不是加热器的输入电量']];$('#ledger').innerHTML=table(['核算项目','本核算窗总量','折算 / 说明'],rows.map(a=>`<tr>${a.map(v=>`<td>${v}</td>`).join('')}</tr>`).join(''));}
function renderCalibration(r){const x=r.selected;if(!Number.isFinite(measured.Tout)||measured.Tout<s.liquidus||measured.Tout>1800||!Number.isFinite(measured.main)||measured.main<=0||!Number.isFinite(measured.aux)||measured.aux<0){$('#calibration').textContent='请输入有效实测值：末温在所设液相线至1800°C之间，主机功率>0，辅机功率≥0。';return;}let loss=0;for(let i=0;i<80;i++)loss+=losses(s,s.Tin+(measured.Tout-s.Tin)*(i+.5)/80,x.g).total/80;const stored=x.g.mass*s.cp*(measured.Tout-s.Tin)/3600,lossE=loss*x.src.durationH,dep=stored+lossE+s.startupKWh,eff=dep/(measured.main*x.src.durationH),net=stored/((measured.main+measured.aux)*x.src.durationH);$('#calibration').innerHTML=`按实测末温和线性温度路径估算散热，反算 <strong>电源主机→钢液沉积效率 ${f(eff*100,1)}%</strong>；计辅机后的<strong>显热净利用率 ${f(net*100,1)}%</strong>。${eff<0||eff>1?'<br><strong>反算效率超出0–100%：热损失、温度测量、功率或边界不一致，不能据此给设备定级。</strong>':''}<br>输入实测功率与末温后独立反算，不会自动覆盖上方假设。此功能针对电加热边界；喷粉另需实测加入量、反应率和气体 / 渣热量。`;}
function renderFormulas(r){const x=r.selected,q=x.initial,g=x.g;const formulas=[['1. 几何、钢液量与停留时间','A顶 = L·W\nA侧 = 2·(L+W)·h\nA接触 = A顶 + A侧\nV = L·W·h，m = ρV\nτ = m / ṁ',`当前A顶=${f(g.top,3)} m²，A接触=${f(g.contact,3)} m²，V=${f(g.volume,3)} m³；连续τ=${f(g.residence,2)} min。热侧面积近似；未含液面以上干壁。`],['2. 耐材接触与向外散热','R材 = 1/h钢 + δ工/k工 + δ保/k保\nq″材 = (T钢 − T壳外) / R材\nq″材 = h外(T壳外−T气)\n       + ε外σ(T壳外,K⁴−T气,K⁴)\nQ̇材 = A接触·q″材',`联立求T壳外，不把钢液到冷空气的温差直接除以耐材厚度。当前q″材=${f(q.wallFlux,3)} kW/m²。参考2022热阻网络；本页另显式加入壳外辐射。`],['3. 渣覆盖与裸露面','q″渣 = (T钢−T渣面)/(1/h钢+δ渣/k渣)\nq″渣 = h顶(T渣面−T气)\n       + ε渣σ(T渣面,K⁴−T辐射环境,K⁴)\nq″裸 = h顶(T钢−T气)\n       + ε钢σ(T钢,K⁴−T辐射环境,K⁴)\nQ̇顶 = A顶·[(1−f裸)q″渣+f裸q″裸]',`覆盖面与裸露面互斥；σ=${SIGMA} W/(m²·K⁴)，辐射温度必须用K。当前渣面温度${f(q.slagTs,1)}°C，非钢液温度。`],['4. 温变与电量（同一能量边界）','单批：m·cₚ·dT/dt = P沉积 − Q̇损 − P蓄热\n连续：ṁ·cₚ·dT/dx = p沉积 − q损(x) − p蓄热\nP电磁 = min(L,L铺设)·p电,m\nP沉积 = η沉积·P主机\nE电 = (P主机+P辅机)·t小时\ne电 = E电 / 处理吨数',`实际连续计算将均布热源转为同等停留时间积分。cₚ单位kJ/(kg·K)，功率kW；批处理质量kg。显示末温、相对初始温变、相对不加热少降温三项。`],['5. 目标功率与喷粉耗量','P需,沉积 = [m·cₚ·ΔT/3600 + E损 + E蓄]/t小时\nP需,主机 = P需,沉积 / η沉积\n粉末理论净热 = H反应·χ·η捕集 − H额外\nm粉/t = E需,沉积(kWh/t)·3.6 / 净热(MJ/kg)\nχ实际 = min(χ设定, O₂供·η氧/(m粉·aO₂))',`目标功率通过温度相关散热迭代求解；目标喷粉量同时给出匹配氧耗，不能保持氧量不变无限加粉。铝/硅/碳标准热分别31.05/32.43/9.20 MJ/kg，均不是高温入钢净热。`],['6. 能量闭合与实测反算','P沉积·t小时 = ΔE钢 + E损 + E蓄\nη沉积,反算 = (ΔE钢,实测+E损,估算+E蓄)/E主机\nη显热净 = ΔE钢,实测/(E主机+E辅机)',`净显热利用率可能为负，表示加热仍不足以抵消散热。沉积效率与净显热利用率不能互换；本页校准按用户实测末温的线性温度路径估计损失。`]];$('#formulas').innerHTML='<div class="formula-grid">'+formulas.map(a=>`<article class="formula"><h3>${a[0]}</h3><code>${a[1]}</code><p>${a[2]}</p></article>`).join('')+`</div><div class="closure">当前方案能量闭合残差：${x.limited?'超出温区，停止核算':f(Math.abs(x.residual),8)+' kWh'}；表面热平衡残差：${f(q.residual,8)} W/m²。数值闭合只验证算术与边界一致，不等于工业精度已验证。</div>`;}
function renderReferences(){const refs=[['R1 · 2022 · 耦合传热模拟','A Simulation-Based Digital Design Methodology for Studying Conjugate Heat Transfer in Tundish','https://doi.org/10.3390/met12010062','支持钢液侧膜阻与分层耐材热阻网络；论文存在不同计算案例。本页两层参数、壳外辐射及几何为独立示例，不声称复现原炉次。'],['R2 · 2022 · 感应加热模拟','Numerical Study on the Influence of Distributing Chamber Volume on Metallurgical Effects in Two-Strand Induction Heating Tundish','https://doi.org/10.3390/met12030509','特定模型顶面热流15、底1.8、长壁4.6、端壁4.0 kW/m²，可用作量级比对；本页热流由温度与热阻求解，不固定套用这些值。'],['R3 · 2024 · 感应器布置模拟','Research on the Relative Placement Angle of the Induction Heater and the Channel in a Four-Channel Induction-Heating Tundish','https://doi.org/10.3390/ma17123011','0/30/60/90°下相对焦耳功率100/98/94/89%，是布置之间的相对量，不能据此填入89%或100%的入钢效率。'],['R4 · 历史设备参考 · 2020','Nippon Steel Engineering · Tundish Plasma Heating','https://www.eng.nipponsteel.com/files_publish/page/155/vol11_09_en.pdf','报告约60%的典型热效率，但其损失边界包含耐材、气体和冷却，不能直接套用到本页“沉积后再扣槽体散热”的边界；本页55%为独立假设。'],['R5 · 标准热化学数据 · NIST','Al₂O₃ α 标准生成焓（298.15 K）','https://webbook.nist.gov/cgi/cbook.cgi?ID=C1344281&Mask=2','−1675.69 kJ/mol，由4Al+3O₂→2Al₂O₃换算31.05 MJ/kg Al；生成热并非进入1600°C钢液的净热。'],['R6 · 标准热化学数据 · NIST','SiO₂ quartz 与 CO 标准生成焓','https://webbook.nist.gov/cgi/cbook.cgi?ID=C14808607&Mask=2','Si+O₂→SiO₂：约32.43 MJ/kg Si。碳仅按2C+O₂→2CO计9.20 MJ/kg，避免把后燃热全部计入钢液。'],['R7 · 标准热化学数据 · NIST','Carbon monoxide · 气相生成焓','https://webbook.nist.gov/cgi/cbook.cgi?ID=C630080&Mask=1','CO标准生成焓−110.5271 kJ/mol；供氧量按0°C、1 atm标准体积换算。氧化副产物增加渣量或尾气，需纳入后续精炼评估。'],['R8 · 物理常数 · NIST','Stefan–Boltzmann constant','https://physics.nist.gov/cgi-bin/cuu/Value?sigma','σ=5.670374419×10⁻⁸ W/(m²·K⁴)。辐射系数、导热系数、界面换热系数及效率默认值均为可编辑假设，未做设备标定。']];$('#citations').innerHTML='<div class="citation-grid">'+refs.map(a=>`<article class="citation"><span class="eyebrow">${a[0]}</span><br><b>${a[1]}</b><p>${a[3]}</p><a href="${a[2]}" target="_blank" rel="noopener noreferrer">查看原始来源 ↗</a></article>`).join('')+'</div>';}
function renderAuxInputs(){$('#target-controls').innerHTML=field('target','目标相对入口温变','°C',{step:1,min:-100,max:100})+'<p>填0表示维持入口温度；填+10表示出槽或保温结束时升温10°C。反算结果包含期间散热，不只是钢液显热。</p>';$('#calibration-controls').innerHTML=`<label class="field" for="measured-Tout"><span>实测末温 · °C</span><input id="measured-Tout" data-measure="Tout" type="number" step=".1" min="1350" max="1800" value="${measured.Tout}"></label><label class="field" for="measured-main"><span>实测平均主机输入 · kW</span><input id="measured-main" data-measure="main" type="number" step="1" min=".1" value="${measured.main}"></label><label class="field" for="measured-aux"><span>实测辅助功率 · kW</span><input id="measured-aux" data-measure="aux" type="number" step="1" min="0" value="${measured.aux}"></label><p>入口温度、处理量 / 时长沿用本页条件；填同一核算时段的实测数据。示例值并非测量结果。</p>`;}
function persist(){try{localStorage.setItem(KEY,JSON.stringify({version:2,state:s,measured}));$('#save-state').textContent='本机自动保存';}catch{$('#save-state').textContent='本机保存不可用';}}
function full(){renderInputs();renderTech();renderAuxInputs();renderResults();}
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.key){s[el.dataset.key]=el.valueAsNumber/(percent.has(el.dataset.key)?100:1);renderResults();}if(el.dataset.measure){measured[el.dataset.measure]=el.valueAsNumber;const r=assess(s);if(!r.errors.length)renderCalibration(r);persist();}});
document.addEventListener('change',e=>{if(e.target.dataset.choice){s[e.target.dataset.choice]=e.target.value;renderResults();}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.mode){s.mode=b.dataset.mode;renderInputs();renderResults();}if(b.dataset.tech){s.selected=b.dataset.tech;renderTech();renderResults();}if(b.dataset.length){s.L=Number(b.dataset.length);$('#h-L').value=s.L;renderResults();}if(b.id==='reset'){s=defaults();measured={Tout:1600,main:480,aux:5};full();}if(b.id==='print')window.print();});
renderReferences();full();
